-- 商品域表（product-service，对应 goods 模块的 C 端商品浏览：商品/分类/标签）
-- 数据来源：e-commerce/server/sqlite/database.sqlite（Node 后端模板店「杰米小店」shopId=1）。
--
-- 执行方式（任选其一）：
--   mysql -u root -p e_commerce_db < docs/sql/product.sql
-- 或在 MySQL 客户端里 source docs/sql/product.sql
--
-- 说明：本脚本只「建表 + 插种子数据」，幂等可重复执行（CREATE TABLE IF NOT EXISTS + INSERT IGNORE），
--       不清空/重建已有表。
--
-- SQLite → MySQL 的几处重设计：
--   1. id 用 BIGINT AUTO_INCREMENT，去掉 SQLite 的 ID_BLOCK 号段偏移 hack（MySQL 全局自增 + 查询带 shop_id 过滤即可）。
--   2. 时间戳 INTEGER（Unix 秒）→ DATETIME（迁移数据用 FROM_UNIXTIME 内联转换）。
--   3. 价格/重量 REAL → DECIMAL。
--   4. categories.product_count 冗余列已去掉：读路径本来就走实时子查询，迁移时不再落这个列；
--      tags.product_count 保留（物化计数，读路径直接读列，写操作维护）。
--   5. 加物理外键：
--      products.tag_id → tags.id              ON DELETE SET NULL（删标签自动解绑商品，对应原 SQLite 行为）
--      products.category_id → categories.id    ON DELETE SET NULL（删分类自动解绑商品）
--      categories.parent_id → categories.id    ON DELETE CASCADE（删父分类级联删除所有子孙分类）
--      InnoDB 会自动为外键列建索引（外键列的固有行为）。

-- ==================== 店铺（多租户沙箱） ====================
CREATE TABLE IF NOT EXISTS `shops` (
    `id`          BIGINT       NOT NULL AUTO_INCREMENT COMMENT '店铺 ID',
    `name`        VARCHAR(128) NOT NULL                COMMENT '店铺名称',
    `is_template` TINYINT      NOT NULL DEFAULT 0      COMMENT '是否模板店：1 是 0 否',
    `create_time` DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `expires_at`  DATETIME     DEFAULT NULL            COMMENT '过期时间（模板店永不过期，为 NULL）',
    `visitor_key` VARCHAR(64)  CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci
                               DEFAULT NULL            COMMENT '访客标识（沙箱复用键；模板店为 NULL）',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_shops_visitor_key` (`visitor_key`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '店铺（多租户沙箱）';

-- ==================== 商品分类（自引用 parent_id 构成分类树） ====================
CREATE TABLE IF NOT EXISTS `categories` (
    `id`         BIGINT       NOT NULL AUTO_INCREMENT COMMENT '分类 ID',
    `shop_id`    BIGINT       NOT NULL DEFAULT 1      COMMENT '所属店铺（模板店=1）',
    `name`       VARCHAR(128) NOT NULL                COMMENT '分类名称',
    `parent_id`  BIGINT       DEFAULT NULL            COMMENT '父分类 ID，顶级分类为 NULL',
    `sort_order` INT          NOT NULL DEFAULT 0      COMMENT '同级排序值，越小越靠前',
    `status`     TINYINT      NOT NULL DEFAULT 1      COMMENT '状态：1 显示 0 隐藏',
    `recommend`  TINYINT      NOT NULL DEFAULT 0      COMMENT '是否推荐：1 是 0 否',
    `image`      VARCHAR(512) DEFAULT NULL            COMMENT '分类图片路径（C 端小程序分类入口展示）',
    PRIMARY KEY (`id`),
    CONSTRAINT `fk_categories_parent` FOREIGN KEY (`parent_id`) REFERENCES `categories`(`id`) ON DELETE CASCADE
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = '商品分类';

-- ==================== 商品标签 ====================
CREATE TABLE IF NOT EXISTS `tags` (
    `id`            BIGINT       NOT NULL AUTO_INCREMENT COMMENT '标签 ID',
    `shop_id`       BIGINT       NOT NULL DEFAULT 1      COMMENT '所属店铺',
    `name`          VARCHAR(128) NOT NULL                COMMENT '标签名称',
    `code`          VARCHAR(64)  DEFAULT NULL            COMMENT '标签编码',
    `type`          VARCHAR(32)  NOT NULL DEFAULT 'custom' COMMENT '标签类型',
    `color`         VARCHAR(32)  NOT NULL DEFAULT '#1890ff' COMMENT '标签颜色',
    `sort_order`    INT          NOT NULL DEFAULT 0      COMMENT '排序值',
    `status`        TINYINT      NOT NULL DEFAULT 1      COMMENT '状态：1 显示 0 隐藏',
    `product_count` INT          NOT NULL DEFAULT 0      COMMENT '关联商品数（物化计数，写操作维护）',
    `create_time`   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `created_by`    BIGINT       DEFAULT NULL            COMMENT '创建人',
    `update_time`   DATETIME     DEFAULT NULL            COMMENT '更新时间',
    `updated_by`    BIGINT       DEFAULT NULL            COMMENT '更新人',
    PRIMARY KEY (`id`)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = '商品标签';

-- ==================== 商品（单规格：价格/库存直接挂在商品上，不做 SKU） ====================
CREATE TABLE IF NOT EXISTS `products` (
    `id`             BIGINT        NOT NULL AUTO_INCREMENT COMMENT '商品 ID',
    `shop_id`        BIGINT        NOT NULL DEFAULT 1      COMMENT '所属店铺',
    `category_id`    BIGINT        DEFAULT NULL            COMMENT '分类 ID',
    `tag_id`         BIGINT        DEFAULT NULL            COMMENT '标签 ID',
    `name`           VARCHAR(255)  NOT NULL                COMMENT '商品名称',
    `sub_title`      VARCHAR(255)  NOT NULL DEFAULT ''     COMMENT '副标题',
    `brand`          VARCHAR(128)  NOT NULL DEFAULT ''     COMMENT '品牌',
    `description`    TEXT                                  COMMENT '商品描述',
    `image`          VARCHAR(512)  DEFAULT NULL            COMMENT '主图',
    `body`           MEDIUMTEXT                             COMMENT '图文详情（富文本）',
    `sales_mode`     VARCHAR(32)   NOT NULL DEFAULT 'spot' COMMENT '销售模式：spot 现货',
    `listing_status` TINYINT       NOT NULL DEFAULT 1      COMMENT '上架状态：1 上架 0 下架',
    `sales_price`    DECIMAL(10,2) NOT NULL DEFAULT 0      COMMENT '售价',
    `market_price`   DECIMAL(10,2) DEFAULT NULL            COMMENT '市场价/划线价',
    `cost_price`     DECIMAL(10,2) DEFAULT NULL            COMMENT '成本价（后台可见，C 端不下发）',
    `product_code`   VARCHAR(64)   DEFAULT NULL            COMMENT '商品编码',
    `stock`          INT           NOT NULL DEFAULT 0      COMMENT '库存',
    `weight`         DECIMAL(10,3) DEFAULT NULL            COMMENT '重量',
    `volume`         DECIMAL(10,3) DEFAULT NULL            COMMENT '体积',
    `create_time`    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `update_time`    DATETIME      DEFAULT NULL            COMMENT '更新时间',
    PRIMARY KEY (`id`),
    CONSTRAINT `fk_products_tag`      FOREIGN KEY (`tag_id`)      REFERENCES `tags`(`id`)       ON DELETE SET NULL,
    CONSTRAINT `fk_products_category` FOREIGN KEY (`category_id`) REFERENCES `categories`(`id`) ON DELETE SET NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COMMENT = '商品（单规格）';

